	private static List<long[]> collect(RecordIterator it) {
		List<long[]> rows = new ArrayList<>();
		try {
			long[] quad;
			while ((quad = it.next()) != null) {
				rows.add(new long[] { quad[TripleIndex.SUBJ_IDX], quad[TripleIndex.PRED_IDX],
						quad[TripleIndex.OBJ_IDX], Math.max(0, quad[TripleIndex.CONTEXT_IDX]) });
			}
		} finally {
			it.close();
		}
		return rows;
	}

