	@Test
	void commitsServeNewSnapshotsWithoutRebuild() throws IOException {
		openStore(null, null);
		long buildsBefore = direct.snapshotMetrics().buildsCompleted;

		try (RepositoryConnection conn = repo.getConnection()) {
			conn.add(S1, P1, O2, G2);
		}
		direct.pauseApplierForTest(false); // deterministic drain

		NativeLmdbQuerySource dataset = dataset();
		try {
			long s1 = dataset.idOf(S1);
			long p1 = dataset.idOf(P1);
			long g2 = dataset.idOf(G2);
			long hitsBefore = direct.snapshotMetrics().lookupHits;
			List<long[]> rows = collect(dataset.statements(s1, p1, -1, -1));
			assertThat(rows).hasSize(2);
			assertThat(direct.snapshotMetrics().lookupHits).isGreaterThan(hitsBefore);
			// bound context through the appended catalog segment
			assertThat(collect(dataset.statements(s1, p1, -1, g2))).hasSize(1);
		} finally {
			((org.eclipse.rdf4j.sail.base.SailDataset) dataset).close();
		}
		assertThat(direct.snapshotMetrics().buildsCompleted).isEqualTo(buildsBefore);
	}

